// ═══════════════════════════════════════════════════════════════════════════
// Helpers
// ═══════════════════════════════════════════════════════════════════════════

export function getModules(): Module[] {
  const moduleMap = new Map<number, Lesson[]>();
  for (const lesson of LESSONS) {
    const existing = moduleMap.get(lesson.module) ?? [];
    existing.push(lesson);
    moduleMap.set(lesson.module, existing);
  }
  return Array.from(moduleMap.entries())
    .sort(([a], [b]) => a - b)
    .map(([num, lessons]) => ({
      number: num,
      name: MODULE_NAMES[num] ?? `Módulo ${num}`,
      lessons: lessons.sort((a, b) => a.order - b.order),
    }));
}

export function getLessonById(id: string): Lesson | undefined {
  return LESSONS.find((l) => l.id === id);
}

export function getLessonsByModule(moduleNumber: number): Lesson[] {
  return LESSONS.filter((l) => l.module === moduleNumber).sort((a, b) => a.order - b.order);
}

export function getNextLesson(currentId: string): Lesson | undefined {
  const current = getLessonById(currentId);
  if (!current) return undefined;
  const moduleLessons = getLessonsByModule(current.module);
  const idx = moduleLessons.findIndex((l) => l.id === currentId);
  if (idx < moduleLessons.length - 1) return moduleLessons[idx + 1];
  const nextModuleLessons = getLessonsByModule(current.module + 1);
  return nextModuleLessons[0];
}

export function getVocabularyById(id: string) {
  const lesson = getLessonById(id);
  return lesson ? lesson.vocabulary : [];
}

export function getCourseStats() {
  const totalLessons = LESSONS.length;
  const totalVocab = LESSONS.reduce((sum, l) => sum + (l.vocabulary?.length || 0), 0);
  const moduleCounts: Record<number, number> = {};
  LESSONS.forEach((l) => {
    moduleCounts[l.module] = (moduleCounts[l.module] || 0) + 1;
  });
  return {
    totalLessons,
    totalVocabulary: totalVocab,
    moduleCounts,
    modules: Object.keys(MODULE_NAMES).length,
  };
}
